import { expect } from 'chai';
import * as zlib from 'zlib';
import { decodeBmp, isBmp } from '../../image/bmp';
import { decodePng } from '../../image/png';
import {
  decodeImage,
  detectImageFormat,
  supportedImageExtensions,
} from '../../image/decode';
import {
  resizeToFit,
  rotateBitmap,
  toMonochrome,
  trimBitmap,
} from '../../image/bitmap';
import { DecodedImage } from '../../image/types';

/**
 * Fixtures are built byte by byte from the file-format specs rather than
 * generated by the decoder's own code, so a decoder that is wrong in a
 * self-consistent way still fails.
 */
function bmpHeader(
  pixelDataSize: number,
  width: number,
  height: number,
  bitsPerPixel: number,
  paletteEntries = 0,
  compression = 0,
): Buffer {
  const paletteBytes = paletteEntries * 4;
  const offset = 14 + 40 + paletteBytes;
  const file = Buffer.alloc(14 + 40);
  file.write('BM', 0, 'ascii');
  file.writeUInt32LE(offset + pixelDataSize, 2);
  file.writeUInt32LE(offset, 10);
  file.writeUInt32LE(40, 14);
  file.writeInt32LE(width, 18);
  file.writeInt32LE(height, 22);
  file.writeUInt16LE(1, 26);
  file.writeUInt16LE(bitsPerPixel, 28);
  file.writeUInt32LE(compression, 30);
  file.writeUInt32LE(pixelDataSize, 34);
  file.writeUInt32LE(paletteEntries, 46);
  return file;
}

function pixelAt(image: DecodedImage, x: number, y: number): number[] {
  const at = (y * image.width + x) * 4;
  return [...image.rgba.subarray(at, at + 4)];
}

describe('image.bmp', () => {
  it('decodes a bottom-up 24-bit BMP', () => {
    // Two rows of two pixels; BMP stores BGR, bottom row first, rows padded to
    // a four-byte boundary.
    const rows = Buffer.concat([
      Buffer.from([0, 0, 255, 0, 255, 0, 0, 0]), // bottom row: red, green
      Buffer.from([255, 0, 0, 255, 255, 255, 0, 0]), // top row: blue, white
    ]);
    const file = Buffer.concat([bmpHeader(rows.length, 2, 2, 24), rows]);

    expect(isBmp(new Uint8Array(file))).to.equal(true);
    const image = decodeBmp(new Uint8Array(file));
    expect([image.width, image.height]).to.deep.equal([2, 2]);
    expect(pixelAt(image, 0, 0)).to.deep.equal([0, 0, 255, 255]); // top-left blue
    expect(pixelAt(image, 1, 0)).to.deep.equal([255, 255, 255, 255]);
    expect(pixelAt(image, 0, 1)).to.deep.equal([255, 0, 0, 255]); // bottom-left red
  });

  it('decodes a top-down BMP (negative height)', () => {
    const rows = Buffer.concat([
      Buffer.from([255, 0, 0, 0, 0, 0, 0, 0]), // top row: blue, black
      Buffer.from([0, 0, 255, 255, 255, 255, 0, 0]), // bottom row: red, white
    ]);
    const header = bmpHeader(rows.length, 2, 2, 24);
    header.writeInt32LE(-2, 22);
    const image = decodeBmp(new Uint8Array(Buffer.concat([header, rows])));
    expect(pixelAt(image, 0, 0)).to.deep.equal([0, 0, 255, 255]);
    expect(pixelAt(image, 0, 1)).to.deep.equal([255, 0, 0, 255]);
  });

  it('decodes a 1-bit palette BMP, the form printer tools emit', () => {
    // Palette: index 0 white, index 1 black. One row of 8 pixels: 10101010.
    const palette = Buffer.from([255, 255, 255, 0, 0, 0, 0, 0]);
    const rows = Buffer.from([0b10101010, 0, 0, 0]);
    const file = Buffer.concat([
      bmpHeader(rows.length, 8, 1, 1, 2),
      palette,
      rows,
    ]);
    const image = decodeBmp(new Uint8Array(file));
    expect(pixelAt(image, 0, 0)).to.deep.equal([0, 0, 0, 255]);
    expect(pixelAt(image, 1, 0)).to.deep.equal([255, 255, 255, 255]);

    // And it converts to exactly the alternating dots a printer would burn.
    const mono = toMonochrome(image);
    expect(mono.bytesPerRow).to.equal(1);
    expect(mono.data[0]).to.equal(0b10101010);
  });

  it('decodes an 8-bit greyscale-palette BMP', () => {
    const palette = Buffer.alloc(256 * 4);
    for (let i = 0; i < 256; i += 1) {
      palette[i * 4] = i;
      palette[i * 4 + 1] = i;
      palette[i * 4 + 2] = i;
    }
    const rows = Buffer.from([0, 128, 255, 0]); // one row, padded to 4 bytes
    const file = Buffer.concat([bmpHeader(rows.length, 3, 1, 8, 256), palette, rows]);
    const image = decodeBmp(new Uint8Array(file));
    expect(pixelAt(image, 0, 0)).to.deep.equal([0, 0, 0, 255]);
    expect(pixelAt(image, 1, 0)).to.deep.equal([128, 128, 128, 255]);
    expect(pixelAt(image, 2, 0)).to.deep.equal([255, 255, 255, 255]);
  });

  it('treats an all-zero alpha channel as opaque, not invisible', () => {
    // Plenty of writers leave the fourth byte of a 32-bit BMP at zero; reading
    // that literally would import a logo as a blank rectangle.
    const rows = Buffer.from([0, 0, 0, 0]); // one black pixel, alpha 0
    const file = Buffer.concat([bmpHeader(rows.length, 1, 1, 32), rows]);
    const image = decodeBmp(new Uint8Array(file));
    expect(pixelAt(image, 0, 0)[3]).to.equal(255);
  });

  it('rejects a file that is not a BMP', () => {
    expect(() => decodeBmp(new Uint8Array([1, 2, 3, 4]))).to.throw('Not a BMP');
  });
});

describe('image.png interlacing', () => {
  /** Writes a PNG, optionally Adam7-interlaced, from an RGBA source. */
  function makePng(
    width: number,
    height: number,
    pixel: (x: number, y: number) => [number, number, number, number],
    interlaced: boolean,
  ): Uint8Array {
    const passes = interlaced
      ? [
          [0, 0, 8, 8],
          [4, 0, 8, 8],
          [0, 4, 4, 8],
          [2, 0, 4, 4],
          [0, 2, 2, 4],
          [1, 0, 2, 2],
          [0, 1, 1, 2],
        ]
      : [[0, 0, 1, 1]];

    const chunks: Buffer[] = [];
    for (const [xStart, yStart, xStep, yStep] of passes) {
      const passWidth = Math.ceil(Math.max(0, width - xStart) / xStep);
      const passHeight = Math.ceil(Math.max(0, height - yStart) / yStep);
      if (passWidth === 0 || passHeight === 0) {
        continue;
      }
      const raw = Buffer.alloc(passHeight * (passWidth * 4 + 1));
      let offset = 0;
      for (let py = 0; py < passHeight; py += 1) {
        raw[offset] = 0; // filter: none
        offset += 1;
        for (let px = 0; px < passWidth; px += 1) {
          const [r, g, b, a] = pixel(xStart + px * xStep, yStart + py * yStep);
          raw[offset] = r;
          raw[offset + 1] = g;
          raw[offset + 2] = b;
          raw[offset + 3] = a;
          offset += 4;
        }
      }
      chunks.push(raw);
    }

    const ihdr = Buffer.alloc(13);
    ihdr.writeUInt32BE(width, 0);
    ihdr.writeUInt32BE(height, 4);
    ihdr[8] = 8; // bit depth
    ihdr[9] = 6; // RGBA
    ihdr[12] = interlaced ? 1 : 0;

    const chunk = (type: string, data: Buffer): Buffer => {
      const length = Buffer.alloc(4);
      length.writeUInt32BE(data.length, 0);
      const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
      const crc = Buffer.alloc(4);
      crc.writeUInt32BE(crc32(body), 0);
      return Buffer.concat([length, body, crc]);
    };

    return new Uint8Array(
      Buffer.concat([
        Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
        chunk('IHDR', ihdr),
        chunk('IDAT', zlib.deflateSync(Buffer.concat(chunks))),
        chunk('IEND', Buffer.alloc(0)),
      ]),
    );
  }

  // A pattern with no symmetry, so a pass assembled in the wrong order shows up.
  const pattern = (x: number, y: number): [number, number, number, number] => [
    (x * 17) % 256,
    (y * 29) % 256,
    (x * y) % 256,
    255,
  ];

  it('decodes an interlaced PNG identically to its progressive twin', () => {
    for (const [width, height] of [
      [13, 11],
      [8, 8],
      [1, 1],
      [3, 17],
    ]) {
      const progressive = decodePng(makePng(width, height, pattern, false));
      const interlaced = decodePng(makePng(width, height, pattern, true));
      expect([interlaced.width, interlaced.height], `${width}x${height}`).to.deep.equal([
        width,
        height,
      ]);
      expect([...interlaced.rgba], `${width}x${height} pixels`).to.deep.equal([
        ...progressive.rgba,
      ]);
    }
  });
});

describe('image.bitmap transforms', () => {
  /** Builds a bitmap from a picture drawn as strings; `#` is a dot. */
  function fromRows(rows: string[]) {
    const width = rows[0].length;
    const image: DecodedImage = {
      width,
      height: rows.length,
      rgba: new Uint8Array(width * rows.length * 4),
    };
    for (let y = 0; y < rows.length; y += 1) {
      for (let x = 0; x < width; x += 1) {
        const value = rows[y][x] === '#' ? 0 : 255;
        const at = (y * width + x) * 4;
        image.rgba[at] = value;
        image.rgba[at + 1] = value;
        image.rgba[at + 2] = value;
        image.rgba[at + 3] = 255;
      }
    }
    return toMonochrome(image);
  }

  function toRows(bitmap: ReturnType<typeof fromRows>): string[] {
    const rows: string[] = [];
    for (let y = 0; y < bitmap.height; y += 1) {
      let row = '';
      for (let x = 0; x < bitmap.width; x += 1) {
        const byte = bitmap.data[y * bitmap.bytesPerRow + (x >> 3)];
        row += (byte >> (7 - (x & 7))) & 1 ? '#' : '.';
      }
      rows.push(row);
    }
    return rows;
  }

  it('trims blank margins', () => {
    const trimmed = trimBitmap(
      fromRows(['........', '..##....', '..#.#...', '........']),
    );
    expect(toRows(trimmed)).to.deep.equal(['##.', '#.#']);
  });

  it('leaves a fully-inked bitmap alone', () => {
    const full = fromRows(['##', '##']);
    expect(toRows(trimBitmap(full))).to.deep.equal(['##', '##']);
  });

  it('returns a blank bitmap unchanged rather than cropping it to nothing', () => {
    const blank = fromRows(['..', '..']);
    const trimmed = trimBitmap(blank);
    expect([trimmed.width, trimmed.height]).to.deep.equal([2, 2]);
  });

  it('rotates clockwise in quarter turns', () => {
    const original = fromRows(['##.', '...']);
    expect(toRows(rotateBitmap(original, 90))).to.deep.equal(['.#', '.#', '..']);
    expect(toRows(rotateBitmap(original, 180))).to.deep.equal(['...', '.##']);
    expect(toRows(rotateBitmap(original, 270))).to.deep.equal(['..', '#.', '#.']);
    expect(toRows(rotateBitmap(original, 0))).to.deep.equal(['##.', '...']);
  });

  it('is its own inverse over four quarter turns', () => {
    const original = fromRows(['#..#', '.##.', '#...']);
    let turned = original;
    for (let i = 0; i < 4; i += 1) {
      turned = rotateBitmap(turned, 90);
    }
    expect(toRows(turned)).to.deep.equal(toRows(original));
  });

  it('applies trim and rotation through toMonochrome options', () => {
    const image: DecodedImage = {
      width: 4,
      height: 4,
      rgba: new Uint8Array(4 * 4 * 4).fill(255),
    };
    // One black dot at (1,1); trimming should reduce the bitmap to that dot.
    const at = (1 * 4 + 1) * 4;
    image.rgba[at] = 0;
    image.rgba[at + 1] = 0;
    image.rgba[at + 2] = 0;
    const bitmap = toMonochrome(image, { trim: true });
    expect([bitmap.width, bitmap.height]).to.deep.equal([1, 1]);
  });

  it('fits an image inside both a width and a height limit', () => {
    const image: DecodedImage = {
      width: 100,
      height: 50,
      rgba: new Uint8Array(100 * 50 * 4).fill(255),
    };
    expect(resizeToFit(image, 50, 0).width).to.equal(50);
    // The tighter of the two limits wins, and the aspect ratio is preserved.
    const fitted = resizeToFit(image, 50, 10);
    expect([fitted.width, fitted.height]).to.deep.equal([20, 10]);
    // An image that already fits is returned as-is, not copied.
    expect(resizeToFit(image, 200, 200)).to.equal(image);
  });
});

describe('image.decode dispatch', () => {
  it('identifies formats by magic bytes', () => {
    const bmp = Buffer.concat([bmpHeader(4, 1, 1, 32), Buffer.from([0, 0, 0, 255])]);
    expect(detectImageFormat(new Uint8Array(bmp))?.id).to.equal('bmp');
    expect(detectImageFormat(new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))?.id).to.equal(
      'png',
    );
    expect(detectImageFormat(new Uint8Array([0xff, 0xd8, 0xff]))).to.equal(undefined);
  });

  it('names the formats it accepts when it cannot decode one', () => {
    expect(() => decodeImage(new Uint8Array([0xff, 0xd8, 0xff]))).to.throw(/PNG or BMP/);
  });

  it('offers every extension to the file dialog', () => {
    expect(supportedImageExtensions()).to.include.members(['png', 'bmp']);
  });
});

function crc32(buffer: Buffer): number {
  let crc = 0xffffffff;
  for (const byte of buffer) {
    crc ^= byte;
    for (let bit = 0; bit < 8; bit += 1) {
      crc = crc & 1 ? (crc >>> 1) ^ 0xedb88320 : crc >>> 1;
    }
  }
  return (crc ^ 0xffffffff) >>> 0;
}
